#define PI    3.1415926535
#define SQRT2 1.41421356237

#define maxDist 10.
#define maxStep 100

vec2 foldRotate(vec2 p, vec2 cs) {
    //diagonal symmetry
    p = (p.y < p.x) ? p : p.yx;
    //rotation + symmetry
    return p - min(dot(p,cs),0.0)*cs;
}

// sdf is here !
float getDist(vec3 p) {

    // parameters :

    int iterations  = 2;
    float size      = 0.25;
    float roundness = 0.5;

    vec2 ang = vec2(-1.25, 1./12.) * PI;

    //

    // rotations are optimised in a weird way for performance
    // (not sure if this is useful)
    vec2 k1 = vec2(cos(ang.x), -sin(ang.x))*SQRT2;
    vec2 k2 = vec2(cos(ang.y), -sin(ang.y))*SQRT2;

    //

    p.z -= 2.*size;

    p.xy = vec2(1.68*size, 0.) - abs(p.xy);
    p.xy = foldRotate(p.xy, k2);

    size *= 0.5;      
    p.xy = abs(p.yx) - vec2(3.4)*size;

    //

    for ( int i = 0; i++ < iterations; ) {

        p.xz = foldRotate(p.xz, k1);
        p.xy = foldRotate(p.xy, k2);
        size *= 0.5;      
        p = abs(p.yxz) - vec3( 4., 1.5, 12. )*size;

    }

    //

    // round box sdf from iq
    vec3 q = abs(p) - (vec3(1.5,12., 1.5 ) - roundness)*size;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - roundness*size;

}

//the floor is not included in the sdf,
//but needed for ao computation
float getDistAndFloor(vec3 p) {
    return min(getDist(p),p.z);
}

//custom ambient occlusion
float ao(vec3 p, vec3 n) {
    float range = 0.1;
    float res  = clamp(getDistAndFloor(p + n*range   ) / range * 2. , 0., 1.) * 0.5
               + clamp(getDistAndFloor(p + n*range*2.) / range      , 0., 1.) * 0.3
               + clamp(getDistAndFloor(p + n*range*4.) / range * 0.5, 0., 1.) * 0.2;

    return res * min(0.5+0.5*length(p-vec3(0.,0.,0.5))*0.8, 1.);
}

// simple raymarching
float rayMarch( vec3 ro, vec3 rd, float tMax ) {

    float t = 0.;
    int i = 0;

    while ( i < maxStep && t < tMax ) {

        float r = abs( getDist( ro + rd*t ) );

        if ( r <= t*0.001 ) break;
        t += r;
        i ++;
    }

    return t;
}

// normal approximation
vec3 distance_field_normal(vec3 pos) {
    vec2 eps = vec2(0.0001,0.0);
    float nx = getDist(pos + eps.xyy);
    float ny = getDist(pos + eps.yxy);
    float nz = getDist(pos + eps.yyx);
    return normalize(vec3(nx, ny, nz) - getDist(pos));
}

// the image is rendered here
// some optimisation is made at the cost of readability
vec3 render( vec3 ro, vec3 rd ) {

    // parameters :

    const vec3 flrCol  = vec3(.75 );
    const vec3 objCol  = vec3( 0.85 );

    const vec3 skyCol1 = vec3( .075, .3,  1. ); // up
    const vec3 skyCol2 = vec3( .35,  .7,  1. ); // down

    vec3 lightDir = normalize(vec3(0.1,0.2,1.));


    //        

    float floorDist = - ro.z / rd.z;
    float maxDist2  = (floorDist > 0.) ? min(maxDist, floorDist) : maxDist;
    float objDist   = rayMarch( ro, rd, maxDist2 );

    if ( floorDist < 0. && objDist > maxDist2 ) {

        //sky
        float sun   = rd.z;
        float horiz = pow(max(1.-abs(rd.z),0.),10.0);
        float light = sun + horiz - horiz * sun ;
        return sqrt(mix(skyCol1, skyCol2, light));

    } 

    vec3 hit, nor, col;
    float specularity, closestDist;

    if (objDist < maxDist2 && (floorDist < 0. || objDist < floorDist) ) {

        //object
        hit = ro + rd*objDist;
        nor = distance_field_normal(hit);
        col = objCol;
        specularity = 0.25;
        closestDist = objDist;            

    } else {

        //floor
        hit = ro + rd*floorDist;
        nor = vec3(0.,0.,1.);
        col = flrCol;
        specularity = 0.;
        closestDist = floorDist;

    }

    float dot1 = dot(lightDir, nor);

    // diffuse + ambient
    float diffuse = mix(max(dot1,0.0), dot1*0.5 + 0.5, 0.75) * (ao(hit, nor)*0.95 + 0.05)*0.97 + 0.03;

    // specular
    vec3 reflectDir = reflect(lightDir,nor);
    float specular  = pow (max (dot (rd, reflectDir), 0.0), 10.0);

    vec3 finalCol = ( col + specular*specularity ) * diffuse;

    // fog
    finalCol = mix(skyCol2, finalCol, exp(-closestDist*0.005));

    return pow(finalCol, vec3(1./2.2));

}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    vec2 p = (2.0*fragCoord.xy - iResolution.xy) / iResolution.y;
    vec2 m = (2.0*iMouse.xy    - iResolution.xy) / iResolution.y;

    // camera angle and matrices
    float ang1 = iTime*0.2 - m.x*2. + 0.75;
    float ang2 = - PI*0.525;// -m.y - PI*0.27;

    vec2 cs1  = vec2(cos(ang1),sin(ang1));
    vec2 cs2  = vec2(cos(ang2),sin(ang2));
    mat2 rot1 = mat2(cs1.yxx,-cs1.y);
    mat2 rot2 = mat2(cs2.yxx,-cs2.y);

    // rounded square wave used to move the camera
    // (work in progress)
    float a = abs(mod(iTime*0.1,2.)-1.);
    float b = 0.4;
    float morph = (clamp(a, b, 1.-b) - b) / (1. - 2.*b); 
    morph = morph*morph*(3.-2.*morph);

    // ray origin and direction
    vec3 ro = vec3( 0., mix(3.5, 1.5, morph), 0.0 );
	vec3 rd = normalize( vec3(p,-2.0) ).xzy;

    rd.yz *= rot2;
    ro.yz *= rot2;

    // camera height
    ro.z += mix(0.8, 0.4, morph);

    rd.xy *= rot1;
    ro.xy *= rot1;

    //

    vec3 finalCol = render( ro, rd );

    fragColor = vec4( finalCol, 1.);

}
